arguments.command:
ruby -e '
def parse_schema(path)
  tables = {}
  File.read(path).scan(/create_table "([^"]+)"(.*?)^  end/m) do |name, body|
    cols = body.scan(/t\.(\w+)\s+"([^"]+)"(.*)/).map { |t, c, rest| [t, c, rest.strip] }
    idxs = body.scan(/t\.index\s+(.*)/).map { |x| x[0].strip }
    tables[name] = { header: body.lines.first.strip, cols: cols, idxs: idxs }
  end
  tables
end

sqlite = parse_schema("db/schema_sqlite.rb")
mysql = parse_schema("db/schema.rb")

puts "Tables ONLY in sqlite: #{sqlite.keys - mysql.keys}"
puts "Tables ONLY in mysql: #{mysql.keys - sqlite.keys}"
puts "\n=== ALL TABLES (#{sqlite.size} in sqlite) ==="
sqlite.sort.each do |name, info|
  acct_col = info[:cols].find { |_, c, _| c == "account_id" }
  acct_idx = info[:idxs].select { |i| i.include?("\"account_id\"") }
  fk_cols = info[:cols].select { |_, c, _| c.end_with?("_id") || c.end_with?("_type") }.map { |t, c, r| "#{c}(#{t}#{r.include?("null: false") ? ",NN" : ""})" }
  puts format("%-32s | acct_col: %-25s | acct_idx: %-4d | fks: %s",
    name,
    acct_col ? "#{acct_col[0]} #{acct_col[2]}" : "MISSING",
    acct_idx.size,
    fk_cols.join(", ")
  )
end
'

